#include <LedControl.h>

// Install the LedControl library using the Arduino IDE Library Manager.
// Constructor order: DIN, CLK, CS, number of MAX7219 devices.
LedControl display(11, 13, 10, 1);

const byte X_PIN = A0;
const byte Y_PIN = A1;
const byte BUTTON_PIN = 2;
const unsigned long MOVE_MS = 220;

// Adjust these if your module orientations differ.
const bool INVERT_X = false;
const bool INVERT_Y = false;
const bool DISPLAY_SWAP_XY = false;
const bool DISPLAY_FLIP_X = false;
const bool DISPLAY_FLIP_Y = false;

struct Cell {
  int8_t x;
  int8_t y;
};

Cell snake[64];
Cell food;
byte snakeLength;
int8_t dx = 1, dy = 0;
int8_t nextDx = 1, nextDy = 0;
unsigned long lastMove = 0;
unsigned long lastDraw = 0;
bool rawButton = HIGH;
bool stableButton = HIGH;
unsigned long buttonChangedAt = 0;

bool occupied(int x, int y) {
  for (byte i = 0; i < snakeLength; ++i) {
    if (snake[i].x == x && snake[i].y == y) return true;
  }
  return false;
}

void placeFood() {
  // Select a free cell without an unbounded random-search loop.
  byte choice = (byte)random(64 - snakeLength);
  for (byte y = 0; y < 8; ++y) {
    for (byte x = 0; x < 8; ++x) {
      if (!occupied(x, y)) {
        if (choice == 0) {
          food.x = x;
          food.y = y;
          return;
        }
        --choice;
      }
    }
  }
}

void restartGame() {
  snakeLength = 3;
  snake[0] = {4, 4};
  snake[1] = {3, 4};
  snake[2] = {2, 4};
  dx = nextDx = 1;
  dy = nextDy = 0;
  placeFood();
  lastMove = millis();
}

void readSteering() {
  int x = analogRead(X_PIN) - 512;
  int y = analogRead(Y_PIN) - 512;
  if (INVERT_X) x = -x;
  if (INVERT_Y) y = -y;

  int8_t candidateDx = 0;
  int8_t candidateDy = 0;
  // A wide centre dead zone prevents unwanted turns.
  if (abs(x) < 220 && abs(y) < 220) return;

  if (abs(x) >= abs(y)) {
    candidateDx = (x > 0) ? 1 : -1;
  } else {
    candidateDy = (y > 0) ? 1 : -1;
  }

  // Compare with the last actual movement, not a queued turn.
  // This prevents reversing into the neck between movement ticks.
  if (candidateDx == -dx && candidateDy == -dy) return;
  nextDx = candidateDx;
  nextDy = candidateDy;
}

void readRestartButton(unsigned long now) {
  bool reading = digitalRead(BUTTON_PIN);
  if (reading != rawButton) {
    rawButton = reading;
    buttonChangedAt = now;
  }
  if (now - buttonChangedAt >= 25 && stableButton != rawButton) {
    stableButton = rawButton;
    if (stableButton == LOW) restartGame();
  }
}

void moveSnake() {
  dx = nextDx;
  dy = nextDy;
  int nx = snake[0].x + dx;
  int ny = snake[0].y + dy;

  if (nx < 0 || nx >= 8 || ny < 0 || ny >= 8) {
    restartGame();
    return;
  }

  bool growing = (nx == food.x && ny == food.y);
  // The old tail cell is available if the tail moves away this tick.
  byte collisionCount = growing ? snakeLength : snakeLength - 1;
  for (byte i = 0; i < collisionCount; ++i) {
    if (snake[i].x == nx && snake[i].y == ny) {
      restartGame();
      return;
    }
  }

  byte newLength = snakeLength + (growing ? 1 : 0);
  for (int i = newLength - 1; i > 0; --i) {
    snake[i] = snake[i - 1];
  }
  snake[0].x = nx;
  snake[0].y = ny;
  snakeLength = newLength;

  if (snakeLength == 64) {
    restartGame();
    return;
  }
  if (growing) placeFood();
}

void addPixel(byte rows[], int x, int y) {
  if (DISPLAY_SWAP_XY) {
    int temporary = x;
    x = y;
    y = temporary;
  }
  if (DISPLAY_FLIP_X) x = 7 - x;
  if (DISPLAY_FLIP_Y) y = 7 - y;
  rows[y] |= (byte)(0x80 >> x);
}

void drawGame(unsigned long now) {
  byte rows[8] = {0};
  for (byte i = 0; i < snakeLength; ++i) {
    addPixel(rows, snake[i].x, snake[i].y);
  }
  // Food blinks; the snake stays steadily lit.
  if ((now % 600UL) < 400UL) addPixel(rows, food.x, food.y);
  for (byte row = 0; row < 8; ++row) {
    display.setRow(0, row, rows[row]);
  }
}

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  display.shutdown(0, false);
  display.setScanLimit(0, 7);
  display.setIntensity(0, 2);
  display.clearDisplay(0);
  randomSeed((unsigned long)analogRead(A2) ^ micros());
  restartGame();
  drawGame(millis());
}

void loop() {
  unsigned long now = millis();
  readRestartButton(now);
  readSteering();

  if (now - lastMove >= MOVE_MS) {
    lastMove = now;
    moveSnake();
  }
  if (now - lastDraw >= 30) {
    lastDraw = now;
    drawGame(now);
  }
}

